fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // k is 1-based, so convert to 0-based index
    let k_zero_based = k - 1;
    
    // Create a new vector with capacity n-1
    let mut result = Vec::with_capacity(list.len() - 1);
    
    // Add all elements before the k-th element
    for i in 0..k_zero_based {
        result.push(list[i]);
    }
    
    // Add all elements after the k-th element
    for i in (k_zero_based + 1)..list.len() {
        result.push(list[i]);
    }
    
    result
}